import org.eclipse.rdf4j.workbench.proxy.WorkbenchServlet;
import org.eclipse.rdf4j.workbench.security.WorkbenchCredentialSession.Credentials;
import org.junit.jupiter.api.Test;

class WorkbenchSessionStateSecurityTest {

	@Test
	void reusesOnlyMatchingServerAndCredentials() {
		WorkbenchSessionState state = new WorkbenchSessionState();
		RecordingServlet original = new RecordingServlet();
		Credentials alice = new Credentials("alice", "secret");

		try (WorkbenchSessionState.Lease first = state.acquire("https://example.org/server", alice, () -> original);
				WorkbenchSessionState.Lease second = state.acquire("https://example.org/server",
						new Credentials("alice", "secret"), RecordingServlet::new)) {
			assertThat(first.servlet()).isSameAs(original);
			assertThat(second.servlet()).isSameAs(original);
		}

		RecordingServlet replacement = new RecordingServlet();
		try (WorkbenchSessionState.Lease lease = state.acquire("https://example.org/server",
				new Credentials("alice", "new-secret"), () -> replacement)) {
			assertThat(lease.servlet()).isSameAs(replacement);
		}
		assertThat(original.destroyCount).isEqualTo(1);
	}

	@Test
	void independentSessionStatesNeverShareCredentialBearingServlets() {
		WorkbenchSessionState aliceState = new WorkbenchSessionState();
		WorkbenchSessionState bobState = new WorkbenchSessionState();
		RecordingServlet alice = new RecordingServlet();
		RecordingServlet bob = new RecordingServlet();

		try (WorkbenchSessionState.Lease aliceLease = aliceState.acquire("https://example.org/server",
				new Credentials("alice", "secret"), () -> alice);
				WorkbenchSessionState.Lease bobLease = bobState.acquire("https://example.org/server",
						new Credentials("bob", "secret"), () -> bob)) {
			assertThat(aliceLease.servlet()).isSameAs(alice);
			assertThat(bobLease.servlet()).isSameAs(bob);
			assertThat(aliceLease.servlet()).isNotSameAs(bobLease.servlet());
		}
	}

	@Test
	void sessionExpiryWaitsForActiveRequestsThenDestroysOwnedServlets() {
		WorkbenchSessionState state = new WorkbenchSessionState();
		RecordingServlet first = new RecordingServlet();
		RecordingServlet second = new RecordingServlet();
		Credentials credentials = new Credentials("alice", "secret");
		WorkbenchSessionState.Lease firstLease = state.acquire("https://one.example/server", credentials, () -> first);
		try (WorkbenchSessionState.Lease ignored = state.acquire("https://two.example/server", credentials,
				() -> second)) {
			// Keep only the first servlet in use while the state closes.
		}

		state.close();
		state.close();

		assertThat(first.destroyCount).isZero();
		assertThat(second.destroyCount).isEqualTo(1);
		firstLease.close();
		assertThat(first.destroyCount).isEqualTo(1);
		assertThatThrownBy(() -> state.acquire("https://one.example/server", credentials,
				RecordingServlet::new)).isInstanceOf(IllegalStateException.class);
	}

	@Test
	void concurrentRequestsCreateOneServletPerSessionCredentialKey() throws Exception {
		WorkbenchSessionState state = new WorkbenchSessionState();
		Credentials credentials = new Credentials("alice", "secret");
		CountDownLatch factoryEntered = new CountDownLatch(1);
		CountDownLatch releaseFactory = new CountDownLatch(1);
		RecordingServlet created = new RecordingServlet();
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<WorkbenchServlet> first = executor.submit(() -> {
				try (WorkbenchSessionState.Lease lease = state.acquire("https://example.org/server", credentials,
						() -> {
							factoryEntered.countDown();
							try {
								releaseFactory.await(5, TimeUnit.SECONDS);
							} catch (InterruptedException e) {
								Thread.currentThread().interrupt();
								throw new IllegalStateException(e);
							}
							return created;
						})) {
					return lease.servlet();
				}
			});
			assertThat(factoryEntered.await(5, TimeUnit.SECONDS)).isTrue();

			AtomicReference<Thread> secondThread = new AtomicReference<>();
			CountDownLatch secondTaskStarted = new CountDownLatch(1);
			Future<WorkbenchServlet> second = executor.submit(() -> {
				secondThread.set(Thread.currentThread());
				secondTaskStarted.countDown();
				try (WorkbenchSessionState.Lease lease = state.acquire("https://example.org/server", credentials,
						RecordingServlet::new)) {
					return lease.servlet();
				}
			});

			assertThat(secondTaskStarted.await(5, TimeUnit.SECONDS)).isTrue();
			assertThat(waitForThreadBlockedOn(secondThread.get(), state, 5, TimeUnit.SECONDS)).isTrue();
			releaseFactory.countDown();

			assertThat(first.get(5, TimeUnit.SECONDS)).isSameAs(created);
			assertThat(second.get(5, TimeUnit.SECONDS)).isSameAs(created);
		} finally {
			releaseFactory.countDown();
			executor.shutdownNow();
		}
	}

	private static boolean waitForThreadBlockedOn(Thread thread, Object lock, long timeout, TimeUnit unit)
			throws InterruptedException {
		long deadline = System.nanoTime() + unit.toNanos(timeout);
		int lockIdentity = System.identityHashCode(lock);
		while (System.nanoTime() < deadline) {
			ThreadInfo info = ManagementFactory.getThreadMXBean()
					.getThreadInfo(new long[] { thread.threadId() }, true, true)[0];
			if (info != null && info.getThreadState() == Thread.State.BLOCKED && info.getLockInfo() != null
					&& info.getLockInfo().getIdentityHashCode() == lockIdentity) {
				return true;
			}
			TimeUnit.MILLISECONDS.sleep(10);
		}
		return false;
	}

	private static final class RecordingServlet extends WorkbenchServlet {
		private int destroyCount;

		@Override
		public void destroy() {
			destroyCount++;
		}
	}
}
